from pathlib import Path

STATUS=Path('status/index.html')
OUT=Path('repair/index.html')
if not STATUS.exists():
    raise RuntimeError('Status page missing before cache repair generation')

status=STATUS.read_text(encoding='utf-8')
if 'id="cacheRepairPanel"' not in status:
    panel='''<section id="cacheRepairPanel" class="panel"><div class="eyebrow">RECUPERACIÓN</div><h2>¿La página se traba o parece desactualizada?</h2><p>Abre la utilidad de reparación para limpiar únicamente el service worker y las cachés de Meta Forge. No borra Watchlist, drafts, perfil ni preferencias.</p><p><a href="../repair/">Reparar caché de Meta Forge →</a></p></section>'''
    if '</main>' not in status:
        raise RuntimeError('Status main closing tag missing')
    status=status.replace('</main>',panel+'</main>',1)
    STATUS.write_text(status,encoding='utf-8')

OUT.parent.mkdir(parents=True,exist_ok=True)
page='''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#070a12"><title>Reparar caché · Meta Forge</title><meta name="description" content="Utilidad local para limpiar únicamente la caché y el service worker de Meta Forge."><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:22px;background:radial-gradient(circle at 15% 0,#173153 0,transparent 34%),#070a12;color:#eef6ff;font-family:system-ui,-apple-system,Segoe UI,sans-serif}.box{width:min(720px,100%);padding:26px;border:1px solid #29405f;border-radius:24px;background:#0b1422;box-shadow:0 24px 70px #0007}.eyebrow{color:#5fe6ff;font-size:10px;font-weight:950;letter-spacing:.14em}h1{font-size:clamp(36px,8vw,62px);letter-spacing:-.055em;margin:8px 0 10px}p{color:#94a6c0;line-height:1.65}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px;margin:18px 0}.cell{padding:12px;border:1px solid #263a55;border-radius:14px;background:#09121f}.cell b{display:block;font-size:15px;overflow-wrap:anywhere}.cell span{display:block;color:#7488a6;font-size:9px;margin-top:4px}.actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:16px}button,a.btn{border:1px solid #35516f;border-radius:12px;background:#0b1b2d;color:#c4d4e8;padding:11px 14px;font:900 11px/1 system-ui;text-decoration:none;cursor:pointer}.primary{background:#58e7ff!important;color:#07111b!important;border-color:#58e7ff!important}.danger-note{margin-top:14px;padding:10px 12px;border-left:3px solid #5fe6ff;background:#09121f;color:#8295b0;font-size:10px}#repairStatus{min-height:20px;color:#8ee9ba;font-size:11px;font-weight:800;margin-top:12px}@media(max-width:560px){.grid{grid-template-columns:1fr}}</style></head><body><main class="box"><div class="eyebrow">META FORGE · REPAIR</div><h1>Reparar caché.</h1><p>Úsalo si la web se queda congelada, carga una interfaz vieja o mezcla comportamientos después de una actualización. Esta herramienta no toca tus datos personales locales.</p><div class="grid"><div class="cell"><b id="repairOnline">Comprobando…</b><span>CONEXIÓN</span></div><div class="cell"><b id="repairBuild">Comprobando…</b><span>BUILD DE RED</span></div><div class="cell"><b id="repairWorkers">Comprobando…</b><span>SERVICE WORKERS DE META FORGE</span></div><div class="cell"><b id="repairCaches">Comprobando…</b><span>CACHÉS MF-SHELL</span></div></div><div class="actions"><button id="repairCache" class="primary" type="button">Reparar caché ahora</button><button id="refreshDiag" type="button">Volver a comprobar</button><a class="btn" href="../status/">Volver a Estado</a></div><div id="repairStatus" role="status" aria-live="polite"></div><p class="danger-note"><b>Se conserva:</b> Watchlist, perfil, drafts, comparaciones recientes y demás datos de <code>localStorage</code>. Solo se eliminan cachés <code>mf-shell-*</code> y registros del service worker cuyo scope pertenece a <code>/mlbb-meta-forge/</code>.</p></main><script id="mf-cache-repair-runtime">(()=>{const APP_SCOPE='/mlbb-meta-forge/';const el=id=>document.getElementById(id);const online=el('repairOnline'),build=el('repairBuild'),workers=el('repairWorkers'),cachesEl=el('repairCaches'),status=el('repairStatus'),repair=el('repairCache'),refresh=el('refreshDiag');async function appWorkers(){if(!('serviceWorker'in navigator))return[];const rows=await navigator.serviceWorker.getRegistrations();return rows.filter(r=>{try{return new URL(r.scope).pathname.startsWith(APP_SCOPE)}catch{return false}})}async function appCaches(){if(!('caches'in window))return[];return (await caches.keys()).filter(k=>k.startsWith('mf-shell-'))}async function inspect(){online.textContent=navigator.onLine?'Online':'Offline';try{const response=await fetch('../data/build-info.json?repair_diag='+Date.now(),{cache:'no-store'});const info=await response.json();build.textContent=info.build_short||'desconocido'}catch{build.textContent='sin respuesta'}try{workers.textContent=String((await appWorkers()).length)}catch{workers.textContent='?'}try{cachesEl.textContent=String((await appCaches()).length)}catch{cachesEl.textContent='?'}}repair.addEventListener('click',async()=>{repair.disabled=true;status.textContent='Limpiando caché de Meta Forge…';try{const regs=await appWorkers();await Promise.all(regs.map(r=>r.unregister()));const keys=await appCaches();await Promise.all(keys.map(k=>caches.delete(k)));status.textContent='Reparación lista. Recargando una copia fresca…';setTimeout(()=>location.replace('../?cache_repaired='+Date.now()),350)}catch(err){status.textContent='No se pudo completar la reparación: '+(err?.message||'error desconocido');repair.disabled=false}});refresh.addEventListener('click',inspect);inspect()})();</script></body></html>'''
OUT.write_text(page,encoding='utf-8')
print('Cache repair utility generated: pwa_runtime=false; local_storage_preserved=true; mf_shell_only=true; status_link=true')
